(()=>{window.__qaEntries=null;(async()=>{try{const r=await (async()=>{const h=await import('/src/studio/assistant/chatHistory.ts');const a=await h.readChatArchive(window.__qaJob);
const t=a?.threads.find(x=>x.id===a.activeId);
return {projectId:a?.projectId??null,activeId:a?.activeId??null,threads:(a?.threads??[]).length,busy:t?.busy??null,error:t?.error??null,
workPacket:t?.workPacket?{state:t.workPacket.state,objective:(t.workPacket.objective||'').slice(0,300),nextAction:t.workPacket.nextAction??null,pendingAction:t.workPacket.pendingAction??null,routingFailure:t.workPacket.routing?.failure??null}:null,
entries:(t?.entries??[]).map(e=>({kind:e.kind,tool:e.toolName??null,failed:e.failed??null,origin:e.executionOrigin??null,projectName:e.projectName??null,projectRevision:e.projectRevision??null,text:e.text}))}})();window.__qaEntries={activeId:r.activeId,entries:r.entries.map((e,i)=>({i,kind:e.kind,tool:e.tool,chars:(e.text||'').length,head:(e.text||'').slice(0,200)}))}}catch(e){window.__qaEntries={error:String(e)}}})();return 'reading entries'})()

(()=>{const log=document.querySelector('.assistant-conversation[role="log"]')||document.querySelector('.assistant-conversation');
if(!log)throw Error('No assistant conversation log');
const rows=[...log.querySelectorAll('.assistant-chat-entry')];
const nodes=rows.length?rows:[...log.children];
const texts=nodes.map(x=>({cls:x.className,text:(x.textContent||'').trim()})).filter(x=>x.text);
return JSON.stringify({rowCount:texts.length,rows:texts.map(t=>({cls:String(t.cls).slice(0,80),chars:t.text.length,head:t.text.slice(0,220)}))})})()

(()=>{const log=document.querySelector('.assistant-conversation[role="log"]')||document.querySelector('.assistant-conversation');
if(!log)throw Error('No assistant conversation log');
const rows=[...log.querySelectorAll('.assistant-chat-entry')];
const nodes=rows.length?rows:[...log.children];
const texts=nodes.map(x=>(x.textContent||'').trim()).filter(Boolean);
const needle="The user is asking again to save the project";
const carrying=texts.filter(t=>t.includes(needle));
return JSON.stringify({rows:texts.length,narrationInRenderedRows:carrying.length>0,
rowsCarryingNarration:carrying.length,narrationInBodyText:document.body.innerText.includes(needle),
firstCarrier:(carrying[0]||'').slice(0,400)})})()
